// src/lib/katalog/marken/antoniolupi.js – antoniolupi (Antonio Lupi Design S.p.A., Stabbia, Cerreto Guidi, Florenz)
// Stand 31.10.2026 (Inhaber-Entscheidung Nr. 25: alle Kategorien mit allen Kollektionen bzw. Hauptmodellen).
//
// Quellen: nur die offizielle Herstellerseite antoniolupi.it (englische Fassung), Kollektionsübersicht
// https://www.antoniolupi.it/en/collections und Produktmenü https://www.antoniolupi.it/en/products mit allen
// Kategorieseiten. Ein Eintrag je Kollektion bzw. Produktseite (Hauptmodell); Varianten (Artikel, Maße,
// Materialien, Farben) als Merkmale + Link zur Herstellerseite. Vollständigkeits-Check:
// qa-screenshots/wellness/produkte/vollstaendigkeit-antoniolupi.md.
//
// Die Seite lädt Bilder per Skript: Seiten wie ein normaler Besucher in Playwright (Standard-Chromium, kein
// gefälschter User-Agent) geöffnet, gescrollt, Bild-URLs aus dem gerenderten DOM (img.currentSrc) gelesen und
// die Originaldatei (/resources/fullhd/…) mit einfachem curl geladen. Motiv unverändert, Dateien einheitlich ≤ 1600 px lange Kante, WebP q82 (tools/images/optimize-katalog.mjs).
// Quelle je Bild: docs/bildquellen/QUELLEN.md (Abschnitt „Katalog antoniolupi“).
//
// Bewusst nicht übernommen: Werbetexte und Wertungen der Herstellerseite (eigene Kurztexte), Farblisten im
// Einzelnen (Verweis auf Herstellerseite), Maße bei mehr als 10 Artikeln (nur die ersten 10 + Verweis),
// Materialgruppen höchstens 5 je Produkt. Zwei Originale waren PNG-Dateien (Transparenz bleibt im WebP).
// Nicht als eigener Eintrag (keine passende Kategorie im Schema, Übergabe): Heizkörper, Kamine, Sessel,
// Betten, Sofas, Wandbeläge, Teppiche, Wohn-Sideboard (Fox) – siehe Vollständigkeits-Check (25 Seiten).

const STAND = "2026-10-31";
const T = (de, en, fr, it) => Object.freeze({ de, en, fr, it });
// typ: "freisteller" (Produkt vor neutralem Grund), "ambiente" (Produkt im Raum) oder "detail".
const bild = (file, width, height, alt, quelleUrl, typ) =>
  Object.freeze({ src: `/Images/Wellness/produkte/antoniolupi/${file}`, width, height, alt, quelleUrl, abgerufen: STAND, typ });
const mass = (key, wert) => Object.freeze({ key, wert });

// Bausteine für die eigenen Kurztexte und Merkmale; die Fakten je Produkt (Typ laut Herstellerkategorie,
// Name, Designer, Artikelanzahl, Materialgruppen, Montagearten) stehen in den Aufrufen unten.
const TYP = {
  sinks: ["Waschtisch","Washbasin","Vasque","Lavabo"],
  showerheads: ["Brause bzw. Duschset","Shower head or shower set","Pomme de douche ou set de douche","Soffione o set doccia"],
  tops: ["Waschtischplatte","Washbasin top","Plan vasque","Top per lavabo"],
  "suspended-tops": ["Hängende Waschtischplatte","Suspended top","Plan suspendu","Top sospeso"],
  taps: ["Armatur","Tap","Robinetterie","Rubinetteria"],
  "sanitary-ware": ["Sanitärobjekt","Sanitary ware","Céramique sanitaire","Sanitario"],
  "shower-trays": ["Duschwanne bzw. Duschabtrennung","Shower tray or enclosure","Receveur ou paroi de douche","Piatto o box doccia"],
  "mirrors-lamps": ["Spiegel","Mirror","Miroir","Specchio"],
  bathtubs: ["Badewanne","Bathtub","Baignoire","Vasca da bagno"],
  "drain-systems": ["Ablaufsystem","Drain system","Système d’évacuation","Sistema di scarico"],
  "drawer-equipment": ["Schubladenausstattung","Drawer equipment","Équipement de tiroir","Attrezzatura per cassetti"],
  furnishings: ["Einrichtungselement","Furnishing element","Élément de mobilier","Complemento d’arredo"],
  accessories: ["Badaccessoire","Bathroom accessory","Accessoire de salle de bains","Accessorio bagno"],
  lamps: ["Leuchte","Lamp","Luminaire","Lampada"],
};
const MAT = {
  Wood: ["Holz","wood","bois","legno"],
  Marbles: ["Marmor","marble","marbre","marmo"],
  Stones: ["Naturstein","stone","pierre","pietra"],
  Cristalmood: ["Cristalmood","Cristalmood","Cristalmood","Cristalmood"],
  Icemood: ["Icemood","Icemood","Icemood","Icemood"],
  Flumood: ["Flumood","Flumood","Flumood","Flumood"],
  Colormood: ["Colormood","Colormood","Colormood","Colormood"],
  Brass: ["Messing","brass","laiton","ottone"],
  Moodlight: ["Moodlight","Moodlight","Moodlight","Moodlight"],
  Glass: ["Glas","glass","verre","vetro"],
  "Flumood Satin": ["Flumood","Flumood","Flumood","Flumood"],
  "Stainless Steel": ["Edelstahl","stainless steel","acier inoxydable","acciaio inox"],
  Acrylic: ["Acryl","acrylic","acrylique","acrilico"],
  Aluminium: ["Aluminium","aluminium","aluminium","alluminio"],
  Ceramic: ["Keramik","ceramic","céramique","ceramica"],
  Cristalplant: ["Cristalplant","Cristalplant","Cristalplant","Cristalplant"],
  "Tempered glass": ["gehärtetes Glas","tempered glass","verre trempé","vetro temperato"],
  Polymer: ["Polymer","polymer","polymère","polimero"],
  "Wood essence": ["Holz","wood","bois","legno"],
  Cork: ["Kork","cork","liège","sughero"],
};
const MONT = {
  boden: ["bodenstehend/freistehend","floor-standing/freestanding","posé au sol/autoportant","a pavimento/freestanding"],
  haengend: ["hängend","suspended","suspendu","sospeso"],
  wand: ["Wandmontage","wall-mounted","montage mural","a parete"],
  einbau: ["Einbau","built-in/recessed","encastré","a incasso"],
  aufsatz: ["Aufsatz","countertop","à poser","da appoggio"],
  decke: ["Deckenmontage","ceiling-mounted","montage au plafond","a soffitto"],
};
const UND = ["und", "and", "et", "e"];
const liste = (xs, i) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} ${UND[i]} ${xs[xs.length - 1]}`);
/** Kurztext: Typ + Name + Design; Artikelanzahl und Materialgruppen laut Herstellerseite. */
function kurzStd(typ, name, des, n, mats) {
  const t = TYP[typ];
  const m = (i) => liste(mats.map((k) => MAT[k][i]), i);
  const d = des ? [`, Design: ${des}`, `, design: ${des}`, `, design : ${des}`, `, design: ${des}`] : ["", "", "", ""];
  const s1 = [`${t[0]} ${name} von antoniolupi${d[0]}.`, `${t[1]} ${name} by antoniolupi${d[1]}.`, `${t[2]} ${name} d’antoniolupi${d[2]}.`, `${t[3]} ${name} di antoniolupi${d[3]}.`];
  let s2 = ["", "", "", ""];
  if (n)
    s2 = [
      ` Laut Hersteller ${n === 1 ? "als ein Artikel" : `in ${n} Artikeln`} erhältlich${mats.length ? `, u. a. aus ${m(0)}` : ""}.`,
      ` According to the manufacturer available as ${n === 1 ? "one item" : `${n} items`}${mats.length ? `, including in ${m(1)}` : ""}.`,
      ` Selon le fabricant, disponible en ${n === 1 ? "un article" : `${n} articles`}${mats.length ? `, notamment en ${m(2)}` : ""}.`,
      ` Secondo il produttore disponibile in ${n === 1 ? "un articolo" : `${n} articoli`}${mats.length ? `, tra l’altro in ${m(3)}` : ""}.`,
    ];
  else if (mats.length) s2 = [` Laut Hersteller aus ${m(0)}.`, ` According to the manufacturer made of ${m(1)}.`, ` Selon le fabricant, en ${m(2)}.`, ` Secondo il produttore in ${m(3)}.`];
  return T(...s1.map((x, i) => x + s2[i]));
}
const artikel = (codes) => {
  const l = codes.slice(0, 16).join(", ") + (codes.length > 16 ? ", …" : "");
  const c = codes.length;
  return T(`Artikel laut Hersteller (${c}): ${l}`, `Items according to the manufacturer (${c}): ${l}`, `Articles selon le fabricant (${c}) : ${l}`, `Articoli secondo il produttore (${c}): ${l}`);
};
const materialien = (ks) => T(...["Materialien: ", "Materials: ", "Matériaux : ", "Materiali: "].map((p, i) => p + ks.map((k) => MAT[k][i]).join(", ")));
const montage = (ks) => T(...["Montage laut Hersteller: ", "Installation according to the manufacturer: ", "Pose selon le fabricant : ", "Installazione secondo il produttore: "].map((p, i) => p + ks.map((k) => MONT[k][i]).join(", ")));
const LED = T("Artikel mit LED-Beleuchtung im Programm", "Items with LED lighting in the range", "Articles avec éclairage LED dans la gamme", "Articoli con illuminazione LED nella gamma");
const FARBEN = T("Farben, Oberflächen und Maße je Artikel siehe Herstellerseite", "Colours, finishes and dimensions per item: see the manufacturer’s page", "Couleurs, finitions et dimensions par article : voir la page du fabricant", "Colori, finiture e misure per articolo: vedere la pagina del produttore");
// Alt-Texte: Titelbild der Herstellerseite bzw. Produktansicht des ersten Artikels.
const altArt = (n, c) => T(`antoniolupi ${n}: Produktansicht des Artikels ${c}`, `antoniolupi ${n}: product view of item ${c}`, `antoniolupi ${n} : vue produit de l’article ${c}`, `antoniolupi ${n}: vista prodotto dell’articolo ${c}`);
const ALT_ILBAGNO = T("antoniolupi IlBagno: Waschtisch auf Holzgestell vor heller Wand", "antoniolupi IlBagno: washbasin on a wooden stand in front of a light wall", "antoniolupi IlBagno : vasque sur piètement en bois devant un mur clair", "antoniolupi IlBagno: lavabo su struttura in legno davanti a una parete chiara");
// Alt-Text nach Bildtyp (Raumbild, Produktfoto vor neutralem Grund, Detail).
const altBild = (n, typ) =>
  typ === "ambiente"
    ? T(`antoniolupi ${n}: Raumbild aus der Präsentation des Herstellers`, `antoniolupi ${n}: room photo from the manufacturer’s presentation`, `antoniolupi ${n} : photo en situation de la présentation du fabricant`, `antoniolupi ${n}: foto in ambiente dalla presentazione del produttore`)
    : typ === "detail"
      ? T(`antoniolupi ${n}: Detailansicht aus der Präsentation des Herstellers`, `antoniolupi ${n}: detail view from the manufacturer’s presentation`, `antoniolupi ${n} : vue de détail de la présentation du fabricant`, `antoniolupi ${n}: vista di dettaglio dalla presentazione del produttore`)
      : T(`antoniolupi ${n}: Produktfoto vor neutralem Hintergrund`, `antoniolupi ${n}: product photo against a neutral background`, `antoniolupi ${n} : photo du produit sur fond neutre`, `antoniolupi ${n}: foto del prodotto su fondo neutro`);

// Konfigurator (Ausführungen): nur Optionen, die auf der jeweiligen Herstellerseite stehen.
// Farb- und Sortennamen sind Herstellerbezeichnungen (unverändert); nur allgemeine englische Wörter übersetzt.
const slugId = (s) =>
  String(s)
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "") || "option";
const FARBNAME = {
  White: T("Weiß", "White", "Blanc", "Bianco"),
  Black: T("Schwarz", "Black", "Noir", "Nero"),
  Graphite: T("Graphit", "Graphite", "Graphite", "Grafite"),
  Red: T("Rot", "Red", "Rouge", "Rosso"),
  Bronze: T("Bronze", "Bronze", "Bronze", "Bronzo"),
  Copper: T("Kupfer", "Copper", "Cuivre", "Rame"),
  "Satin Stainless Steel": T("Edelstahl satiniert", "Satin stainless steel", "Acier inoxydable satiné", "Acciaio inox satinato"),
  "Polished Stainless Steel": T("Edelstahl poliert", "Polished stainless steel", "Acier inoxydable poli", "Acciaio inox lucido"),
  "Polished Chrome": T("Chrom poliert", "Polished chrome", "Chrome poli", "Cromo lucido"),
  "Bleached Oak": T("Eiche gebleicht", "Bleached oak", "Chêne blanchi", "Rovere sbiancato"),
  "natural cork": T("Kork natur", "Natural cork", "Liège naturel", "Sughero naturale"),
  "toasted cork": T("Kork geröstet", "Toasted cork", "Liège torréfié", "Sughero tostato"),
  "Lacquered as per our color samples": T("Lackiert nach Farbmustern des Herstellers", "Lacquered to the manufacturer’s colour samples", "Laqué selon les échantillons du fabricant", "Laccato secondo i campioni colore del produttore"),
  "Painted as per our color samples": T("Lackiert nach Farbmustern des Herstellers", "Painted to the manufacturer’s colour samples", "Peint selon les échantillons du fabricant", "Verniciato secondo i campioni colore del produttore"),
};
const optionen = (names) => {
  const seen = new Set();
  const out = [];
  for (const n of names) {
    const id = slugId(n);
    if (seen.has(id)) continue;
    seen.add(id);
    out.push(Object.freeze({ id, name: FARBNAME[n] || n }));
  }
  return Object.freeze(out);
};
const ausfMaterial = (ks) =>
  Object.freeze({ gruppe: T("Material", "Material", "Matériau", "Materiale"), optionen: Object.freeze(ks.map((k) => Object.freeze({ id: slugId(k), name: T(...MAT[k].map((x) => x.charAt(0).toUpperCase() + x.slice(1))) }))) });
const ausfFarben = (k, names) =>
  Object.freeze({
    gruppe: T(`${MAT[k][0]} – Farben und Sorten`, `${MAT[k][1]} – colours and types`, `${MAT[k][2]} – couleurs et types`, `${MAT[k][3]} – colori e tipi`),
    optionen: optionen(names),
  });
const ausfArtikel = (list) => {
  const seen = new Set();
  const opts = [];
  list.forEach(([code, dim], i) => {
    let id = slugId(code);
    if (seen.has(id)) id = `${id}-${i + 1}`;
    seen.add(id);
    opts.push(Object.freeze({ id, name: dim ? `${code} (${dim})` : code, code }));
  });
  return Object.freeze({ gruppe: T("Artikel und Maße", "Items and dimensions", "Articles et dimensions", "Articoli e misure"), optionen: Object.freeze(opts) });
};
const ausfMontage = (ks) =>
  Object.freeze({ gruppe: T("Montage", "Installation", "Pose", "Installazione"), optionen: Object.freeze(ks.map((k) => Object.freeze({ id: k, name: T(...MONT[k]) }))) });

// Zubehör: nur Kombinationen, die die Herstellerseite gemeinsam zeigt oder ausdrücklich nennt.
const Z_GEZEIGT = T("Auf der Herstellerseite gemeinsam gezeigt", "Shown together on the manufacturer’s page", "Présentés ensemble sur la page du fabricant", "Mostrati insieme sulla pagina del produttore");
const Z_KOMBI = T("Laut Herstellerseite miteinander kombinierbar", "Can be combined according to the manufacturer’s page", "Combinables selon la page du fabricant", "Abbinabili secondo la pagina del produttore");
const Z_GELIEFERT = T("Laut Herstellerseite wird das WC mit dem Sitz FLAT geliefert", "According to the manufacturer’s page the toilet comes with the FLAT seat", "Selon la page du fabricant, le WC est livré avec l’abattant FLAT", "Secondo la pagina del produttore il vaso è fornito con il sedile FLAT");
const zub = (slug, hinweis) => Object.freeze({ slug, hinweis });

